):?><div class="alert alert-danger"><?= htmlspecialchars($errorMessage) ?></div><?php endif;?>
<?php if($clearanceSection==='general'):?><form method="post" class="cls-panel"><input type="hidden" name="action" value="save_clearance_section"><?= csrfTokenField() ?><div class="cls-head"><h2 class="h5 mb-1">Clearance controls</h2><p class="small text-muted mb-0">These rules apply to supported clearance requests and generated PDFs.</p></div><div class="cls-body"><div class="cls-grid"><?php foreach([['online_requests_enabled','Enable online clearance requests','Residents can submit clearance applications online.'],['qr_verification_enabled','Enable QR verification','Allow verification scans for clearance documents.'],['essential_details_only','Essential resident details only','Limit processing views to required resident information.'],['copy_has_signature','Released-copy signatures','Show uploaded official signatures on released copies.'],['print_header_enabled','Add barangay header when printed','Turn off when using paper with an existing letterhead.']] as [$key,$label,$copy]):?><label class="cls-option"><div class="form-check form-switch"><input class="form-check-input" type="checkbox" name="<?= $key ?>" <?= !empty($clearanceSettings[$key])?'checked':'' ?>><span class="fw-semibold ms-2"><?= htmlspecialchars($label) ?></span></div><div class="small text-muted ms-5"><?= htmlspecialchars($copy) ?></div></label><?php endforeach;?></div><hr><h3 class="h6 fw-bold">Generated document fields</h3><div class="cls-grid"><?php foreach(dms_document_field_catalog('monitoring') as $key=>$label):?><label class="cls-option"><span class="form-check form-switch"><input class="form-check-input" type="checkbox" name="document_field_visible[<?= htmlspecialchars($key) ?>]" <?= !empty($clearanceSettings['document_field_visibility'][$key])?'checked':'' ?>><span class="ms-2 fw-semibold">Show <?= htmlspecialchars($label) ?></span></span></label><?php endforeach;?></div><hr><div class="row g-3"><div class="col-md-4"><label class="form-label fw-semibold">Default validity</label><div class="input-group"><input class="form-control" type="number" min="1" max="365" name="default_validity_days" value="<?= (int)$clearanceSettings['default_validity_days'] ?>"><span class="input-group-text">days</span></div></div><div class="col-md-8"><label class="form-label fw-semibold d-block">Allowed validity choices</label><div class="d-flex flex-wrap gap-3 pt-2"><?php foreach([3,7,15,30,45,60,90,180,365] as $days):?><label class="form-check"><input class="form-check-input" type="checkbox" name="allowed_validity_days[]" value="<?= $days ?>" <?= in_array($days,(array)$clearanceSettings['allowed_validity_days'],true)?'checked':'' ?>> <?= $days ?> days</label><?php endforeach;?></div></div></div><div class="text-end mt-4"><button class="btn btn-cls px-4">Save General Settings</button></div></div></form><?php endif;?>
<?php if($clearanceSection==='types'):?><form method="post" class="cls-panel"><input type="hidden" name="action" value="save_clearance_section"><?= csrfTokenField() ?><div class="cls-head"><h2 class="h5 mb-1">Clearance catalog</h2><p class="small text-muted mb-0">Enable supported forms and enter one purpose option per line.</p></div><div class="cls-body"><div class="cls-grid"><?php foreach(dms_clearance_type_catalog() as $key=>$label):$row=$clearanceSettings['clearance_types'][$key]??[];?><section class="cls-type"><div class="cls-type-head"><strong><?= htmlspecialchars($label) ?></strong><div class="form-check form-switch"><input class="form-check-input" type="checkbox" name="clearance_type_enabled[<?= htmlspecialchars($key) ?>]" <?= !empty($row['enabled'])?'checked':'' ?>></div></div><div class="cls-type-body"><label class="form-label small fw-semibold">Purpose options</label><textarea class="form-control" rows="5" name="purpose_options[<?= htmlspecialchars($key) ?>]"><?= htmlspecialchars(implode("\n",(array)($row['purpose_options']??[]))) ?></textarea></div></section><?php endforeach;?></div><div class="text-end mt-4"><button class="btn btn-cls px-4">Save Clearance Types</button></div></div></form><?php endif;?>
<?php if($clearanceSection==='notifications'):?><form method="post" class="cls-panel"><input type="hidden" name="action" value="save_clearance_section"><?= csrfTokenField() ?><div class="cls-head"><h2 class="h5 mb-1">Resident messages</h2><p class="small text-muted mb-0">Placeholders: {request_id}, {document_type}, {reason}, {count}, {days}</p></div><div class="cls-body"><?php foreach((array)$clearanceSettings['resident_notifications'] as $event=>$notice):?><div class="cls-notice"><label class="form-check form-switch"><input class="form-check-input" type="checkbox" name="notification_enabled[<?= htmlspecialchars($event) ?>]" <?= !empty($notice['enabled'])?'checked':'' ?>><span class="fw-semibold text-capitalize"><?= htmlspecialchars(str_replace('_',' ',$event)) ?></span></label><textarea class="form-control" rows="2" name="notification_message[<?= htmlspecialchars($event) ?>]"><?= htmlspecialchars((string)$notice['message']) ?></textarea></div><?php endforeach;?><div class="cls-option mt-3"><label class="form-check form-switch"><input class="form-check-input" type="checkbox" name="aging_notification_enabled" <?= !empty($clearanceSettings['aging_notification_enabled'])?'checked':'' ?>><span class="fw-semibold">Aging-request notification</span></label><div class="row g-3 mt-1"><div class="col-md-3"><label class="form-label">Threshold</label><div class="input-group"><input class="form-control" type="number" min="1" max="90" name="aging_days" value="<?= (int)$clearanceSettings['aging_days'] ?>"><span class="input-group-text">days</span></div></div><div class="col-md-9"><label class="form-label">Message</label><textarea class="form-control" rows="2" name="aging_message"><?= htmlspecialchars((string)$clearanceSettings['aging_message']) ?></textarea></div><div class="col-12"><label class="form-label">Recipients</label><select class="form-select" name="aging_recipient_mode" id="clearanceRecipientMode"><option value="module_access" <?= ($clearanceSettings['aging_recipient_mode']??'')==='module_access'?'selected':'' ?>>All employees with Clearance Issuance access</option><option value="specific" <?= ($clearanceSettings['aging_recipient_mode']??'')==='specific'?'selected':'' ?>>Only selected employees</option></select></div><div class="col-12" id="clearanceRecipientSelection"><div class="cls-recipients"><?php foreach($notificationRecipientOptions as $recipient):$uid=(string)$recipient['user_id'];?><label class="form-check cls-option"><input class="form-check-input" type="checkbox" name="aging_recipient_user_ids[]" value="<?= htmlspecialchars($uid) ?>" <?= in_array($uid,(array)($clearanceSettings['aging_recipient_user_ids']??[]),true)?'checked':'' ?>><span><strong><?= htmlspecialchars((string)$recipient['name']) ?></strong><small class="d-block text-muted"><?= htmlspecialchars((string)$recipient['position']) ?></small></span></label><?php endforeach;?></div></div></div></div><div class="text-end mt-4"><button class="btn btn-cls px-4">Save Notification Settings</button></div></div></form><?php endif;?>
</main></div><script src="https://cdn.jsdelivr.net/npm/bootstrap@5.3.0/dist/js/bootstrap.bundle.min.js"></script><?php if($clearanceSection==='notifications'):?><script>(()=>{const m=document.getElementById('clearanceRecipientMode'),s=document.getElementById('clearanceRecipientSelection'),sync=()=>s?.classList.toggle('d-none',m?.value!=='specific');m?.addEventListener('change',sync);sync();})();</script><?php endif;?></body></html>
